pub(super) fn finish(call: &mut HostCall<'_>, store: &Shared, id: TableId) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        if let Some(clock) = &mut store.replay_clock {
            clock.reset(id);
        }
        let actor = store.actors.get_mut(&id).unwrap();
        if !capture::cancel(actor, true) {
            if let Some(last) = actor.queue.back() {
                actor.current = last.to;
            }
            actor.queue.clear();
            actor.sync_rotation_getters();
        }
    }
    song_immediate::cancel(call, store, id, true);
    song_messages::reset_timing(call, store, id)?;
    song_replay::sync_getters(call, store, id)?;
    // Finish also visits native named children. Hurry, TimeLeft and ordinary
    // frame updates retain the production traversal of authored children only.
    for child in children(call, store, id)? {
        finish(call, store, child)?;
    }
    Ok(())
}

fn hurry(store: &mut Store, id: TableId, factor: f32) {
    if let Some(clock) = &mut store.replay_clock {
        clock.hurry(id, factor);
    }
    let actor = store.actors.get_mut(&id).unwrap();
    for step in &mut actor.queue {
        step.duration *= factor;
        step.left *= factor;
    }
    if let Some(capture) = &mut actor.capture {
        capture.hurry(factor);
    }
    for child in actor.children.clone() {
        hurry(store, child, factor);
    }
}

pub(super) fn time_left(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
) -> Result<f32, Error> {
    call.with_roots(&[Value::Table(id)], |call| {
        if let Some(state) = transitions::state(call, id)? {
            return if state == 1 {
                match transitions::child(call, id)? {
                    Some(child) => time_left(call, store, child),
                    None => Ok(0.),
                }
            } else {
                Ok(0.)
            };
        }
        let theme_hibernating = !matches!(
            get(call, id, b"__songlua_theme_hibernating")?,
            Value::Nil | Value::Boolean(false)
        );
        let native = {
            let store = store.lock().unwrap();
            store.actors.get(&id).map(|actor| {
                let hibernate = if theme_hibernating {
                    f32::INFINITY
                } else {
                    actor.hibernate
                };
                (
                    hibernate,
                    actor.capture.as_ref().map_or_else(
                        || {
                            actor
                                .queue
                                .iter()
                                .fold(hibernate, |left, step| left + step.left)
                        },
                        |capture| hibernate + capture.time_left.max(0.),
                    ),
                )
            })
        };
        let (hibernate, mut left) = if let Some(native) = native {
            native
        } else {
            let value = get(call, id, b"__songlua_hibernate_seconds")?;
            let hibernate = if theme_hibernating {
                f32::INFINITY
            } else if value == Value::Nil {
                0.
            } else {
                sprites::number(call, value)? as f32
            };
            let value = sprites::field(call, id, "__songlua_capture_tween_time_left")?;
            let left = if value == Value::Nil {
                0.
            } else {
                (sprites::number(call, value)? as f32).max(0.)
            };
            (hibernate, hibernate + left)
        };
        let mut index = 1;
        loop {
            let value = call.raw_table_get(id, Value::Number(index as f64))?;
            if value == Value::Nil {
                break;
            }
            if let Value::Table(child) = value {
                let child = hibernate + time_left(call, store, child)?;
                if left < child {
                    left = child;
                }
            }
            index += 1;
        }
        Ok(left)
    })
}

fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    exact_duration: f64,
    easing: &str,
    command: Option<Vec<u8>>,
) -> Result<(), Error> {
    let duration = exact_duration as f32;
    capture::enter_replay_queue(store, id);
    // BeginTweening finishes the actor subtree before adding its 52nd state.
    let count = {
        let guard = store.lock().unwrap();
        let actor = &guard.actors[&id];
        actor
            .capture
            .as_ref()
            .map_or(actor.queue.len(), capture::Capture::pending_steps)
    };
    if count > 50 {
        finish(call, store, id)?;
    }
    let mut store = store.lock().unwrap();
    if let Some(clock) = &mut store.replay_clock {
        clock.tween(
            id,
            if command.is_some() {
                None
            } else {
                Some(exact_duration)
            },
        );
    }
    let queued = store.capture_scope.is_some();
    let replaying = store.replay_frame.is_some();
    let actor = store.actors.get_mut(&id).unwrap();
    if replaying {
        actor.replay.get_or_insert_with(song_replay::State::default);
    }
    let index = actor.replay.as_mut().map(|replay| {
        let index = replay.progress.len();
        replay.progress.push(Vec::new());
        replay.capture_open = command.is_none();
        index
    });
    if let Some(capture) = &mut actor.capture {
        capture.begin_tween(duration, easing, queued);
        if !actor.active_commands.is_empty() {
            capture.exact_step(exact_duration);
        }
    }
    let to = *actor.destination();
    let command_step = command.is_some();
    actor.queue.push_back(TweenStep {
        index,
        duration,
        left: duration,
        from: None,
        to,
        easing: easing.to_owned(),
        opt1: None,
        command,
    });
    drop(store);
    if replaying {
        song_messages::timing(
            call,
            id,
            if command_step { 0. } else { duration },
            (!command_step).then_some(easing),
        )?;
    }
    Ok(())
}

fn duration(call: &HostCall<'_>, value: Value, sleep: bool) -> f64 {
    // The production numeric helpers parse string durations as Rust floats,
    // but reject nonfinite numeric values (Sleep retains positive infinity).
    let value = match value {
        Value::Number(value) if value.is_finite() || (sleep && value == f64::INFINITY) => {
            Some(value)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|text| std::str::from_utf8(text).ok())
            .and_then(|text| text.trim().parse::<f64>().ok()),
        _ => None,
    };
    value.unwrap_or(0.0).max(0.0)
}

fn native_tween(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let duration = call.number(1)? as f32;
    if duration < 0.0 {
        return Ok(());
    }
    if duration.is_nan() {
        return Err(call.error(b"invalid tween duration"));
    }
    let names = [
        "TweenType_Linear",
        "TweenType_Accelerate",
        "TweenType_Decelerate",
        "TweenType_Spring",
        "TweenType_Bezier",
    ];
    let kind = match arg(call, 2) {
        Value::Number(index) if (0.0..5.0).contains(&index) && index.fract() == 0.0 => {
            Some(index as usize)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|name| std::str::from_utf8(name).ok())
            .and_then(|name| {
                names.iter().position(|full| {
                    name == *full || name.eq_ignore_ascii_case(full.split_once('_').unwrap().1)
                })
            }),
        _ => None,
    }
    .ok_or_else(|| call.error(b"Expected TweenType"))?;
    let easing = if kind == 4 {
        let controls = table(call, arg(call, 3))?;
        let count = call.raw_table_len(controls)?;
        if count != 4 && count != 8 {
            return Ok(());
        }
        let mut points = Vec::with_capacity(count);
        for index in 1..=count {
            let value = call.raw_table_get(controls, Value::Number(index as f64))?;
            let value = call.call(helper(call, 6)?, &[value])?[0];
            let value = if let Value::Number(value) = value {
                value as f32
            } else {
                0.0
            };
            points.push(value.to_string());
        }
        format!("bezier({})", points.join(","))
    } else {
        ["linear", "inQuad", "outQuad", "spring"][kind].to_owned()
    };
    queue(call, store, actor, f64::from(duration), &easing, None)
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    op: Lifecycle,
) -> Result<(), Error> {
    if matches!(op, Lifecycle::Update | Lifecycle::Rate | Lifecycle::GetRate)
        && !is_frame(store, actor)
    {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Lifecycle::Ease(easing) => {
            let duration = duration(call, arg(call, 1), false);
            queue(call, store, actor, duration, easing, None)?;
        }
        Lifecycle::Tween => native_tween(call, store, actor)?,
        Lifecycle::Sleep => {
            let duration = duration(call, arg(call, 1), true);
            queue(call, store, actor, duration, "linear", None)?;
            queue(call, store, actor, 0.0, "linear", None)?;
        }
        Lifecycle::Hibernate => {
            let key = call.try_intern(b"__songlua_theme_hibernating")?;
            call.raw_table_set(actor, key, Value::Boolean(false))?;
            let duration = float_scalar(call, arg(call, 1), true).unwrap_or(0.0);
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .hibernate = duration;
            let key = call.try_intern(b"__songlua_hibernate_seconds")?;
            call.raw_table_set(actor, key, Value::Number(duration as f64))?;
            capture::write(
                call,
                store,
                actor,
                crate::SongLuaOverlayStateDelta {
                    hibernating: Some(duration > 0.),
                    ..Default::default()
                },
                true,
            );
        }
        Lifecycle::Stop => {
            {
                let mut store = store.lock().unwrap();
                if let Some(clock) = &mut store.replay_clock {
                    clock.reset(actor);
                }
                let actor = store.actors.get_mut(&actor).unwrap();
                if !capture::cancel(actor, false) {
                    actor.queue.clear();
                    actor.sync_rotation_getters();
                }
            }
            song_immediate::cancel(call, store, actor, false);
            song_messages::reset_timing(call, store, actor)?;
            song_replay::sync_getters(call, store, actor)?;
        }
        Lifecycle::Finish => finish(call, store, actor)?,
        Lifecycle::Hurry => {
            let factor = call.number(1)? as f32;
            if factor < 0.0 {
                return Err(call.error(b"hurrytweening factor must not be negative"));
            }
            hurry(&mut store.lock().unwrap(), actor, factor);
            song_messages::hurry_timing(call, store, actor, factor)?;
        }
        Lifecycle::TimeLeft => {
            let left = time_left(call, store, actor)?;
            return call.push(Value::Number(left as f64));
        }
        Lifecycle::Queue | Lifecycle::QueueMessage => {
            if let Some(mut name) = command_name(call, arg(call, 1)) {
                if matches!(op, Lifecycle::QueueMessage) {
                    name.insert(0, b'!');
                }
                if !capture::queue(call, store, actor, name.clone())? {
                    queue(call, store, actor, 0.0, "linear", Some(name))?;
                }
            }
        }
        Lifecycle::Update => {
            let function = arg(call, 1);
            if !matches!(function, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"SetUpdateFunction requires a function or nil"));
            }
            let key = call.try_intern(b"__songlua_update_function")?;
            call.table_set(Value::Table(actor), key, function)?;
            invalidate_plans(call, store)?;
        }
        Lifecycle::Rate => {
            let rate = call.number(1)? as f32;
            if rate <= 0.0 {
                return Err(call.error(b"Update rate must be greater than 0"));
            }
            if rate > 0.0 {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .update_rate = rate;
                invalidate_plans(call, store)?;
            }
        }
        Lifecycle::GetRate => {
            return call.push(Value::Number(
                store.lock().unwrap().actors[&actor].update_rate as f64,
            ));
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn start(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    play(call, store, actor, b"Begin", None, true)?;
    startup(call, store, actor)
}

pub(super) fn end(call: &mut HostCall<'_>, store: &Shared, root: TableId) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let key = call.try_intern(b"__songlua_top_screen")?;
    call.raw_table_set(globals, key, Value::Nil)?;
    // The production live scene owns a synthetic root. End walks its ordinary
    // descendants in their current order, excluding that root and wrappers.
    // Commands may append tweens/queues, but End never advances them.
    for child in children(call, store, root)? {
        play(call, store, child, b"End", None, true)?;
    }
    Ok(())
}

pub(super) fn startup(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, true);
    }
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    run_named(call, store, actor, b"On", None)?;
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        startup(call, store, child)?;
    }
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        startup(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .started = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_startup_commands_ran")?;
    Ok(())
}

fn advance_queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
    span: f32,
) -> Result<(), Error> {
    let mut remaining = delta;
    // A meter stream hidden by an already initialized duplicate-name group
    // has never subscribed. Its stored queue/getters remain observable, but
    // production does not advance that queue without native registration.
    if !store.lock().unwrap().actors[&actor].registered {
        return Ok(());
    }
    let mut dispatched = 0;
    // Commands can replace the queue. Release metadata before entering Lua and
    // consume the original frame's remaining native float time afterwards.
    while remaining > 0.0 {
        let command = {
            let mut store = store.lock().unwrap();
            let sync = !store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
            let time = store.replay_frame.map_or(0., |(_, time)| time as f32);
            let actor = store.actors.get_mut(&actor).unwrap();
            let Some(step) = actor.queue.front_mut() else {
                break;
            };
            let beginning = step.from.is_none();
            if beginning {
                step.from = Some(actor.current);
                if let (Some(replay), Some(index)) = (&mut actor.replay, step.index) {
                    let start = if step.duration == 0. {
                        time
                    } else {
                        time - span * (remaining / delta)
                    };
                    replay.progress[index].push([start, step.duration]);
                }
            }
            let command = if beginning { step.command.take() } else { None };
            let used = remaining.min(step.left);
            step.left -= used;
            remaining -= used;
            if let (Some(replay), Some(index)) = (&mut actor.replay, step.index) {
                replay.progress[index].push([time, step.left]);
            }
            if step.left == 0.0 {
                actor.current = step.to;
                actor.queue.pop_front();
            } else {
                let factor = crate::overlay_command_ease_factor(
                    Some(&step.easing),
                    1.0 - step.left / step.duration,
                    step.opt1,
                );
                actor.current = step.from.unwrap().lerp(step.to, factor);
            }
            if sync {
                actor.sync_rotation_getters();
            }
            command
        };
        song_replay::sync_getters(call, store, actor)?;
        if let Some(command) = command {
            dispatched += 1;
            if dispatched > 10000 {
                return Err(call.error(b"nonterminating zero-time actor command queue"));
            }
            song_messages::reset_timing(call, store, actor)?;
            let previous = {
                let mut guard = store.lock().unwrap();
                let time = guard
                    .replay_frame
                    .map(|(_, time)| song_immediate::Dispatch {
                        seconds: Some(time),
                        delay: 0.,
                    });
                std::mem::replace(&mut guard.replay_dispatch, time)
            };
            let previous_clock = store
                .lock()
                .unwrap()
                .replay_clock
                .as_mut()
                .and_then(|clock| clock.dispatched(actor, remaining));
            let result = if let Some(message) = command.strip_prefix(b"!") {
                messages::queued(call, store, message)
            } else {
                play(call, store, actor, &command, None, true)
            };
            store.lock().unwrap().replay_dispatch = previous;
            if let Some(clock) = &mut store.lock().unwrap().replay_clock {
                clock.dispatch = previous_clock;
            }
            result?;
        }
    }
    Ok(())
}

pub(super) struct FrameNode {
    actor: TableId,
    owned: bool,
    transition: bool,
    wrappers: Vec<FrameNode>,
    children: Vec<FrameNode>,
    columns: Vec<FrameNode>,
    order: usize,
    callback_order: usize,
}
pub(super) struct Plan {
    roots: TableId,
    node: FrameNode,
    orders: Arc<HashMap<TableId, usize>>,
}
pub(super) fn invalidate_plans(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let plans = std::mem::take(&mut store.lock().unwrap().update_plans);
    let registry = table(call, call.captures()[0])?;
    for plan in plans.into_values() {
        call.raw_table_set(registry, Value::Table(plan.roots), Value::Nil)?;
    }
    Ok(())
}
fn plan(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    roots: TableId,
) -> Result<FrameNode, Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let owned = store.lock().unwrap().actors.contains_key(&actor);
        let (wrappers, children) = if owned {
            let store = store.lock().unwrap();
            let node = &store.actors[&actor];
            (node.wrappers.clone(), node.children.clone())
        } else {
            // Generated duplicate-name groups have no raw native pose or queue.
            // The cached traversal still owns their table and visits their array.
            call.raw_table_set(roots, Value::Table(actor), Value::Boolean(true))?;
            (Vec::new(), native_children::group_members(call, actor)?)
        };
        let wrappers = wrappers
            .into_iter()
            .map(|id| plan(call, store, id, roots))
            .collect::<Result<_, _>>()?;
        let mut nodes = Vec::new();
        for child in children {
            native_children::adopt_declared(call, store, child, actor)?;
            nodes.push(plan(call, store, child, roots)?);
        }
        if owned && let Some(stream) = song_meters::stream(call, store, actor)? {
            nodes.push(plan(call, store, stream, roots)?);
        }
        let mut columns = Vec::new();
        for column in notefields::update_columns(call, actor)? {
            columns.push(plan(call, store, column, roots)?);
        }
        Ok(FrameNode {
            actor,
            owned,
            transition: transitions::state(call, actor)?.is_some(),
            wrappers,
            children: nodes,
            columns,
            order: 0,
            callback_order: 0,
        })
    })
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    // Production retains its traversal until an invalidating operation such as
    // SetUpdateFunction/SetUpdateRate. SortByDrawOrder alone does not invalidate
    // it. The current frame keeps its original plan even across invalidation;
    // callback values themselves are still resolved at the time of invocation.
    let cached = store.lock().unwrap().update_plans.get(&actor).cloned();
    let plan = if let Some(plan) = cached {
        plan
    } else {
        let roots = call.try_new_table()?;
        let plan = call.with_roots(&[Value::Table(roots)], |call| {
            let mut node = plan(call, store, actor, roots)?;
            let mut orders = HashMap::new();
            assign_orders(&mut node, &mut 0, &mut orders);
            let registry = table(call, call.captures()[0])?;
            call.raw_table_set(registry, Value::Table(roots), Value::Boolean(true))?;
            Ok(Arc::new(Plan {
                roots,
                node,
                orders: Arc::new(orders),
            }))
        })?;
        store
            .lock()
            .unwrap()
            .update_plans
            .insert(actor, plan.clone());
        plan
    };
    // An authored callback may invalidate the cache and collect while this
    // frame still uses the original plan's proxy groups.
    let prior_phase = {
        let mut guard = store.lock().unwrap();
        guard.replay_clock.as_mut().and_then(|clock| {
            clock.orders = plan.orders.clone();
            clock.phase.take()
        })
    };
    let result = call.with_roots(&[Value::Table(plan.roots)], |call| {
        advance_node(call, store, &plan.node, delta, delta)
    });
    if let Some(clock) = &mut store.lock().unwrap().replay_clock {
        clock.phase = prior_phase;
    }
    result
}

fn assign_orders(node: &mut FrameNode, counter: &mut usize, orders: &mut HashMap<TableId, usize>) {
    for wrapper in &mut node.wrappers {
        assign_orders(wrapper, counter, orders);
    }
    *counter += 1;
    node.order = *counter;
    orders.insert(node.actor, *counter);
    for child in &mut node.children {
        assign_orders(child, counter, orders);
    }
    node.callback_order = *counter;
    for column in &mut node.columns {
        assign_orders(column, counter, orders);
    }
}

fn enter_phase(store: &Shared, order: usize, delta: f32) {
    if let Some(clock) = &mut store.lock().unwrap().replay_clock {
        clock.enter(order, delta);
    }
}

fn advance_node(
    call: &mut HostCall<'_>,
    store: &Shared,
    node: &FrameNode,
    delta: f32,
    span: f32,
) -> Result<(), Error> {
    let actor = node.actor;
    let material_delta = delta;
    let material_span = span;
    let delta = if !node.owned {
        delta
    } else {
        let mut guard = store.lock().unwrap();
        let actor = guard.actors.get_mut(&actor).unwrap();
        if actor.hibernate > 0.0 {
            let left = actor.hibernate - delta;
            actor.hibernate = left.max(0.0);
            drop(guard);
            let key = call.try_intern(b"__songlua_hibernate_seconds")?;
            call.raw_table_set(node.actor, key, Value::Number(left.max(0.0) as f64))?;
            if left <= 0.0 {
                song_immediate::record(
                    call,
                    store,
                    node.actor,
                    crate::SongLuaOverlayUpdateTarget::Hibernating,
                    crate::SongLuaOverlayUpdateValue::Bool(false),
                );
                -left
            } else {
                models::advance_materials(store, node.actor, material_delta);
                for column in &node.columns {
                    advance_node(call, store, column, material_delta, material_span)?;
                }
                return Ok(());
            }
        } else {
            delta
        }
    };
    let span = if material_delta > 0. {
        span * (delta / material_delta)
    } else {
        0.
    };
    // Wrappers receive the owner's post-hibernation delta before its update
    // rate. Their callbacks can change that rate for this same frame.
    for wrapper in &node.wrappers {
        advance_node(call, store, wrapper, delta, span)?;
    }
    let delta = if node.owned {
        let delta = delta * store.lock().unwrap().actors[&actor].update_rate;
        enter_phase(store, node.order, delta);
        effects::advance(call, store, actor, delta)?;
        advance_queue(call, store, actor, delta, span)?;
        enter_phase(store, node.order, delta);
        recurring::advance(call, store, actor, delta)?;
        delta
    } else {
        delta
    };
    // Transition::UpdateInternal follows the owner's base queue, gates its
    // children and update callback, and tests completion before the final child
    // update. A cached plan retains whether this actor has a transition job.
    let children_active = if node.transition {
        let state = transitions::state(call, actor)?
            .ok_or_else(|| call.error(b"transition state expected"))?;
        if state != 1 {
            false
        } else {
            if let Some(child) = transitions::child(call, actor)?
                && time_left(call, store, child)? == 0.
            {
                sprites::set(call, actor, "__songlua_transition_state", Value::Number(2.))?;
            }
            true
        }
    } else {
        true
    };
    if children_active {
        for child in &node.children {
            advance_node(call, store, child, delta, span)?;
        }
    }
    models::advance_materials(store, actor, material_delta);
    enter_phase(store, node.callback_order, delta);
    let function = get(call, actor, b"__songlua_update_function")?;
    if children_active && function != Value::Nil {
        if !matches!(function, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"actor update function must be a function"));
        }
        let result = call.with_roots(&[function], |call| {
            run_scoped(call, actor, function, Some(Value::Number(delta as f64)))
        });
        match result {
            Err(error) if error.kind() == ErrorKind::Runtime => {
                let mut store = store.lock().unwrap();
                if let Some(actor) = store.actors.get_mut(&actor) {
                    if !actor.update_error_reported {
                        actor.update_error_reported = true;
                        store.diagnostics.push(error.to_string());
                    }
                } else {
                    store.diagnostics.push(error.to_string());
                }
            }
            result => result?,
        }
    }
    // NoteField advances its column vector after its frame callback, using the
    // incoming delta outside the frame's hibernation and update-rate gates.
    for column in &node.columns {
        advance_node(call, store, column, material_delta, material_span)?;
    }
    Ok(())
}

/// Even an actor paused by an ancestor contributes a hold sample for the
/// compiler's currently running tween. Unstarted queues have no progress yet.
pub(super) fn sample_replay(actor: &mut Actor, time: f32) {
    if let (Some(replay), Some(step)) = (&mut actor.replay, actor.queue.front())
        && let Some(index) = step.index
        && step.from.is_some()
        && replay.progress[index]
            .last()
            .is_none_or(|sample| sample[0] != time)
    {
        replay.progress[index].push([time, step.left]);
    }
}

/// Message writes keep the delay of the real existing queue, including sleep
/// and hibernation; it cannot be reconstructed from the last command alone.
pub(super) fn message_delay(actor: &Actor, duration: f32) -> f32 {
    if duration > 0. {
        actor
            .queue
            .iter()
            .take(actor.queue.len().saturating_sub(1))
            .fold(actor.hibernate, |left, step| left + step.left)
    } else {
        0.
    }
}

//! Compiler-owned prediction of fallback queue clocks over canonical frames.
use super::*;

#[derive(Default)]
struct Queue {
    progress: Option<Arc<[[f32; 2]]>>,
    epoch: usize,
    frame: usize,
    remaining: f64,
    zero_frame: Option<usize>,
    steps: VecDeque<Option<f64>>,
    blocked: bool,
    dispatch: Option<(usize, f64)>,
}
#[derive(Clone, Copy)]
pub(super) struct Phase {
    pub order: usize,
    pub delta: f64,
}
#[derive(Clone, Copy)]
pub(super) struct Dispatch {
    pub actor: TableId,
    pub frame: usize,
    pub remaining: f64,
}
pub(super) struct Publication {
    pub cursor: Option<f32>,
    pub progress: Option<Arc<[[f32; 2]]>>,
    pub advance: f32,
}
pub(super) struct State {
    times: Vec<f64>,
    actor_frames: Option<Vec<[f32; 2]>>,
    pub frame: usize,
    epoch: usize,
    native: HashSet<TableId>,
    clocks: HashMap<TableId, Queue>,
    timing: HashMap<TableId, (f32, f32)>,
    pub orders: Arc<HashMap<TableId, usize>>,
    pub phase: Option<Phase>,
    pub dispatch: Option<Dispatch>,
}
impl State {
    pub fn new(
        frames: &[(f64, f64)],
        actor_frames: Option<&[[f32; 2]]>,
        native: HashSet<TableId>,
    ) -> Self {
        let mut seconds = 0.;
        Self {
            times: frames
                .iter()
                .map(|(_, dt)| {
                    seconds += dt;
                    seconds
                })
                .collect(),
            actor_frames: actor_frames.map(<[_]>::to_vec),
            frame: 0,
            epoch: 0,
            native,
            clocks: HashMap::new(),
            timing: HashMap::new(),
            orders: Arc::default(),
            phase: None,
            dispatch: None,
        }
    }
    pub fn time(&self, frame: usize) -> f64 {
        self.times.get(frame).copied().unwrap_or_else(|| {
            self.times.last().copied().unwrap_or(0.)
                + frame.saturating_sub(self.times.len()).saturating_add(1) as f64 / 60.
        })
    }
    fn delta(&self, frame: usize) -> f64 {
        if let Some(delta) = self.actor_frames.as_ref().and_then(|f| f.get(frame)) {
            return f64::from(delta[0]);
        }
        if frame == 0 {
            0.
        } else {
            f64::from(self.time(frame) as f32 - self.time(frame - 1) as f32)
        }
    }
    fn global_remainder(&self, frame: usize, remaining: f64) -> f64 {
        self.actor_frames
            .as_ref()
            .and_then(|f| f.get(frame))
            .map_or(remaining, |[delta, span]| {
                if *delta > 0. {
                    remaining * f64::from(*span) / f64::from(*delta)
                } else {
                    0.
                }
            })
    }
    fn order(&self, id: TableId) -> usize {
        self.orders.get(&id).copied().unwrap_or(0)
    }
    pub fn enter(&mut self, order: usize, delta: f32) {
        self.phase = Some(Phase {
            order,
            delta: f64::from(delta),
        });
        self.epoch += 1;
    }
    pub fn reset(&mut self, id: TableId) {
        self.clocks.remove(&id);
        self.timing.remove(&id);
    }
    pub fn hurry(&mut self, id: TableId, factor: f32) {
        if let Some((cursor, duration)) = self.timing.get_mut(&id) {
            *cursor = (*cursor + duration.max(0.)) * factor;
            *duration = 0.;
        }
        if let Some(clock) = self.clocks.get_mut(&id) {
            for d in clock.steps.iter_mut().flatten() {
                *d = f64::from(*d as f32 * factor);
            }
            clock.progress = None;
        }
    }
    pub fn tween(&mut self, id: TableId, duration: Option<f64>) {
        if self.native.contains(&id) {
            return;
        }
        let (cursor, prior) = self.timing.entry(id).or_default();
        *cursor += prior.max(0.);
        *prior = 0.;
        if let Some(delay) = self.record(id, duration) {
            self.timing.get_mut(&id).unwrap().0 = delay;
        }
        if let Some(duration) = duration {
            self.timing.get_mut(&id).unwrap().1 = duration as f32;
        } else if let Some(mut clock) = self.clocks.remove(&id) {
            if clock.dispatch.is_none() {
                while let Some(step) = clock.steps.pop_front() {
                    advance(self, &mut clock, step.unwrap_or(0.), None);
                    if step.is_none() {
                        clock.dispatch = Some((clock.frame, clock.remaining));
                        break;
                    }
                }
            }
            self.clocks.insert(id, clock);
        }
    }
    fn record(&mut self, id: TableId, duration: Option<f64>) -> Option<f32> {
        let phase = self.phase?;
        let later = self.order(id) > phase.order;
        let (frame, remaining) = self
            .dispatch
            .map(|d| {
                (
                    d.frame,
                    if d.actor == id {
                        d.remaining
                    } else if self.order(id) > self.order(d.actor) {
                        self.delta(d.frame)
                    } else {
                        0.
                    },
                )
            })
            .unwrap_or((self.frame, if later { phase.delta } else { 0. }));
        let mut clock = self.clocks.remove(&id).unwrap_or(Queue {
            epoch: self.epoch,
            frame,
            remaining,
            ..Default::default()
        });
        let changed = clock.epoch != self.epoch;
        if changed && clock.dispatch.is_none() {
            while let Some(step) = clock.steps.pop_front() {
                advance(self, &mut clock, step.unwrap_or(0.), None);
            }
            clock.epoch = self.epoch;
        }
        if clock.steps.is_empty()
            && (clock.frame < frame || (clock.frame == frame && clock.remaining > remaining))
        {
            clock.frame = frame;
            clock.remaining = remaining;
        }
        let delay = changed.then(|| {
            (self.time(clock.frame) - clock.remaining - (self.time(frame) - remaining)).max(0.)
                as f32
        });
        clock.steps.push_back(duration);
        clock.progress = None;
        self.clocks.insert(id, clock);
        delay
    }
    pub fn flush(&mut self, id: TableId) {
        if let Some((cursor, duration)) = self.timing.get_mut(&id) {
            *cursor += duration.max(0.);
            *duration = 0.;
        }
    }
    pub fn dispatched(&mut self, id: TableId, remaining: f32) -> Option<Dispatch> {
        let prior = self.dispatch;
        let mut time = (self.frame, f64::from(remaining));
        if !self.native.contains(&id)
            && let Some(mut clock) = self.clocks.remove(&id)
        {
            if let Some(dispatch) = clock.dispatch.take() {
                time = dispatch;
            }
            self.timing
                .insert(id, (clock.steps.iter().flatten().sum::<f64>() as f32, 0.));
            clock.epoch = self.epoch;
            self.clocks.insert(id, clock);
        }
        self.dispatch = Some(Dispatch {
            actor: id,
            frame: time.0,
            remaining: time.1,
        });
        prior
    }
    fn progress(&mut self, id: TableId) -> Option<Arc<[[f32; 2]]>> {
        let mut clock = self.clocks.remove(&id)?;
        if clock.progress.is_none() && !clock.steps.is_empty() {
            let mut sample = Queue {
                epoch: clock.epoch,
                frame: clock.frame,
                remaining: clock.remaining,
                zero_frame: clock.zero_frame,
                blocked: clock.blocked,
                ..Default::default()
            };
            let mut samples = Vec::new();
            for (index, duration) in clock.steps.iter().enumerate() {
                advance(
                    self,
                    &mut sample,
                    duration.unwrap_or(0.),
                    (index + 1 == clock.steps.len()).then_some(&mut samples),
                );
            }
            if !samples.is_empty() {
                clock.progress = Some(samples.into());
            }
        }
        let progress = clock.progress.clone();
        self.clocks.insert(id, clock);
        progress
    }
    pub fn publication(&mut self, id: TableId) -> Publication {
        let native = self.native.contains(&id);
        let (cursor, duration) = self.timing.get(&id).copied().unwrap_or_default();
        let timed = cursor.max(0.) > f32::EPSILON || duration.max(0.) > f32::EPSILON;
        let empty = self
            .clocks
            .get(&id)
            .is_some_and(|c| c.steps.back() == Some(&Some(0.)));
        let progress = if native {
            None
        } else if timed {
            self.progress(id)
        } else if empty {
            let progress = self.progress(id);
            let later = self.phase.is_some_and(|p| self.order(id) > p.order);
            progress.filter(|p| {
                later
                    || p.first()
                        .is_some_and(|s| s[0] > self.time(self.frame) as f32)
            })
        } else {
            None
        };
        let advance = if let Some(scope) = self.dispatch {
            let advance = if scope.actor == id {
                scope.remaining
            } else if self.order(id) > self.order(scope.actor) {
                self.delta(scope.frame)
            } else {
                0.
            };
            (self.time(self.frame) - self.time(scope.frame) + advance) as f32
        } else {
            self.phase
                .filter(|p| self.order(id) > p.order)
                .map_or(0., |p| p.delta as f32)
        };
        Publication {
            cursor: (!native).then_some(cursor.max(0.)),
            progress,
            advance,
        }
    }
}

fn advance(
    frames: &State,
    clock: &mut Queue,
    duration: f64,
    mut samples: Option<&mut Vec<[f32; 2]>>,
) {
    if clock.blocked || !(duration as f32).is_finite() {
        clock.blocked = true;
        return;
    }
    // Actor::UpdateTweening subtracts native floats on each frame. A double
    // clock can release a zero-time command early and change later RNG calls.
    let mut left = duration as f32;
    loop {
        while clock.remaining <= 0.0 {
            let Some(frame) = clock.frame.checked_add(1) else {
                clock.blocked = true;
                return;
            };
            clock.frame = frame;
            clock.remaining = frames.delta(clock.frame);
        }
        if duration as f32 == 0.0 {
            clock.zero_frame = Some(clock.frame);
        }
        // A callback after its child can enqueue a zero-time state on the final
        // captured frame. Its start still belongs to the next update, even when
        // that update lies beyond the replay. Omitting this sample makes the
        // pending destination look immediate and overwrites the last draw.
        if let Some(samples) = &mut samples
            && samples.is_empty()
        {
            let start = frames.time(clock.frame)
                - if left == 0.0 {
                    0.0
                } else {
                    frames.global_remainder(clock.frame, clock.remaining)
                };
            let mut start = start as f32;
            if left > 0.0 && clock.frame > 0 {
                let prior = frames.time(clock.frame - 1) as f32;
                // A tiny remainder can put the next tween strictly after the
                // prior update while both timestamps round to the same float.
                // Preserve queue order: it cannot draw on that earlier frame.
                if frames.time(clock.frame) - frames.global_remainder(clock.frame, clock.remaining)
                    > f64::from(prior)
                    && start <= prior
                {
                    start = prior.next_up();
                }
            }
            if let Some(frame) = clock.zero_frame {
                start = start.max(frames.time(frame) as f32);
            }
            samples.push([start, left]);
        }
        let elapsed = left.min(clock.remaining as f32);
        left -= elapsed;
        clock.remaining = f64::from(clock.remaining as f32 - elapsed);
        if let Some(samples) = &mut samples
            && clock.frame < frames.times.len()
            && left != duration as f32
        {
            samples.push([frames.time(clock.frame) as f32, left]);
        }
        if left == 0.0 {
            break;
        }
        if clock.frame >= frames.times.len() {
            let count = (left * 60.0).floor() as usize;
            if count > 1 {
                clock.frame = clock.frame.saturating_add(count - 1);
                left -= (count - 1) as f32 / 60.0;
            }
        }
    }
}

impl Actors {
    pub(in crate::rust_engine) fn discard_song_replay_clock(&self) {
        self.store.lock().unwrap().replay_clock = None;
    }

    pub(in crate::rust_engine) fn set_song_replay_frames(
        &self,
        screen: ActorScene,
        frames: &[(f64, f64)],
        actor_frames: Option<&[[f32; 2]]>,
    ) -> bool {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame.map(|f| f.0) != Some(screen.id)
            || store.replay_advancing
            || store.clock.live.load(std::sync::atomic::Ordering::Relaxed)
        {
            return false;
        }
        let native = store
            .actors
            .iter()
            .filter(|(_, a)| a.scene == screen.id && a.capture.is_none())
            .map(|(id, _)| *id)
            .collect();
        store.replay_clock = Some(State::new(frames, actor_frames, native));
        true
    }
    pub(in crate::rust_engine) fn set_song_replay_frame(
        &self,
        screen: ActorScene,
        frame: usize,
    ) -> Option<f64> {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        let clock = store.replay_clock.as_mut()?;
        clock.frame = frame;
        Some(clock.time(frame))
    }
}

//! Preparation callbacks retained by the non-startup capture scheduler.
use super::*;

#[derive(Clone, Default)]
pub(super) struct State {
    pub(super) command: Option<Vec<u8>>,
    pub(super) interval: f64,
    pub(super) remaining: Option<f64>,
    pub(super) running: bool,
    error_reported: bool,
}

fn invoke(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    command: &[u8],
    queued: Option<f32>,
) -> Result<(), Error> {
    let (prior, prior_clock) = {
        let mut guard = store.lock().unwrap();
        let prior_clock = if let Some(remaining) = queued {
            guard.replay_clock.as_mut().and_then(|clock| {
                clock.reset(actor);
                clock.dispatched(actor, remaining)
            })
        } else {
            guard.replay_clock.as_ref().and_then(|clock| clock.dispatch)
        };
        let time = guard.replay_frame.map(|(_, time)| time);
        let target = guard.actors.get_mut(&actor).unwrap();
        let capture = target.capture.as_mut().unwrap();
        capture.reset_command();
        capture.recurring.command = None;
        capture.recurring.running = true;
        target.queue.clear();
        let prior = guard.replay_dispatch;
        if queued.is_some() {
            guard.replay_dispatch = Some(song_immediate::Dispatch {
                seconds: time,
                delay: 0.,
            });
        }
        (prior, prior_clock)
    };
    let result = (|| {
        song_messages::timing(call, actor, 0., None)?;
        for key in [
            "__songlua_capture_cursor",
            "__songlua_capture_tween_time_left",
        ] {
            song_replay::raw_set(call, actor, key, Value::Number(0.))?;
        }
        song_replay::raw_set(call, actor, "__songlua_capture_opt2", Value::Nil)?;
        // This scheduler invokes the actor's own named command. ActorFrame's
        // recursive PlayCommand dispatch is a separate queue path.
        run_named(call, store, actor, command, None)
    })();
    let mut guard = store.lock().unwrap();
    guard.replay_dispatch = prior;
    if let Some(clock) = &mut guard.replay_clock {
        clock.dispatch = prior_clock;
    }
    let recurring = &mut guard
        .actors
        .get_mut(&actor)
        .unwrap()
        .capture
        .as_mut()
        .unwrap()
        .recurring;
    recurring.running = false;
    match result {
        Err(error) if error.kind() == ErrorKind::Runtime => {
            if !recurring.error_reported {
                recurring.error_reported = true;
                guard.diagnostics.push(format!(
                    "{}Command: {error}",
                    String::from_utf8_lossy(command)
                ));
            }
            Ok(())
        }
        result => result,
    }
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    let (command, mut interval, mut left) = {
        let guard = store.lock().unwrap();
        if guard.replay_frame.is_none()
            || guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
        {
            return Ok(());
        }
        let actor = &guard.actors[&actor];
        if !actor.registered {
            return Ok(());
        }
        let Some(capture) = &actor.capture else {
            return Ok(());
        };
        let recurring = &capture.recurring;
        let Some(command) = &recurring.command else {
            return Ok(());
        };
        (
            command.clone(),
            recurring.interval,
            recurring.remaining.unwrap_or(recurring.interval) as f32,
        )
    };
    // The native zero-interval branch runs once per active update, including
    // a zero or negative delta, and carries no queued publication scope.
    if interval <= f64::EPSILON {
        return invoke(call, store, actor, &command, None);
    }
    let mut delta = delta.max(0.);
    let mut runs = 0;
    while delta > 0. && runs < 64 {
        if left > 0. {
            let used = left.min(delta);
            left -= used;
            delta -= used;
            if delta == 0. {
                break;
            }
        }
        invoke(call, store, actor, &command, Some(delta))?;
        {
            let mut guard = store.lock().unwrap();
            let recurring = &mut guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap()
                .recurring;
            if recurring.command.is_none() {
                recurring.remaining = None;
                return Ok(());
            }
            interval = recurring.interval;
        }
        runs += 1;
        if interval <= f64::EPSILON {
            break;
        }
        left = interval as f32;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .capture
        .as_mut()
        .unwrap()
        .recurring
        .remaining = Some(f64::from(left));
    Ok(())
}

//! Compiler buffers shared by immediate and scheduled render setters.
use super::super::{SongReplayImmediateUpdates, SongReplayScheduledUpdate};
use super::*;
use crate::{SongLuaOverlayUpdateTarget as Target, SongLuaOverlayUpdateValue as UpdateValue};

// The order within compound setters matters (notably basezoom and Load's size
// and texture writes). Effects emit their own ordered sequence of writes.
pub(crate) const TARGETS: &[Target] = &[
    Target::Visible,
    Target::Hibernating,
    Target::HAlign,
    Target::VAlign,
    Target::TextAlign,
    Target::BaseZoom,
    Target::BaseZoomX,
    Target::BaseZoomY,
    Target::BaseZoomZ,
    Target::BaseAlpha,
    Target::BaseRotation,
    Target::ShadowLen,
    Target::ShadowColor,
    Target::Size,
    Target::SpriteTexture,
    Target::SpriteStateIndex,
    Target::Vibrate,
    Target::Rainbow,
    Target::EffectMode,
    Target::EffectPeriod,
    Target::EffectTiming,
    Target::EffectMagnitude,
    Target::EffectColor1,
    Target::EffectColor2,
    Target::EffectOffset,
    Target::EffectClock,
    Target::EffectNoOffset,
    Target::EffectTimer,
    Target::CullMode,
    Target::AftPreserve,
    Target::AftCreated,
];

#[derive(Clone, Copy)]
pub(super) struct Dispatch {
    pub(super) seconds: Option<f64>,
    pub(super) delay: f32,
}

#[derive(Default)]
pub(super) struct Capture {
    touched: Vec<usize>,
    frames: HashMap<usize, SongReplayImmediateUpdates>,
    pending: HashMap<usize, Vec<(Target, UpdateValue)>>,
}

fn replace(values: &mut Vec<(Target, UpdateValue)>, target: Target, value: UpdateValue) {
    if let Some((_, old)) = values.iter_mut().find(|(key, _)| *key == target) {
        *old = value;
    } else {
        values.push((target, value));
    }
}

impl Capture {
    pub(super) fn touch(&mut self, index: usize) -> &mut SongReplayImmediateUpdates {
        self.frames.entry(index).or_insert_with(|| {
            self.touched.push(index);
            SongReplayImmediateUpdates {
                overlay_index: index,
                ..Default::default()
            }
        })
    }

    pub(super) fn record(
        &mut self,
        index: usize,
        target: Target,
        value: UpdateValue,
        scheduled: Option<SongReplayScheduledUpdate>,
    ) {
        let pending = self
            .pending
            .get(&index)
            .and_then(|values| values.iter().find(|(key, _)| *key == target))
            .map(|(_, value)| value.clone());
        let frame = self.touch(index);
        replace(&mut frame.final_values, target, value.clone());
        if let Some(mut update) = scheduled {
            if let Some(previous) = frame.scheduled.iter_mut().find(|prior| {
                prior.target == target
                    && prior.dispatch_seconds == update.dispatch_seconds
                    && prior.frame_advance == update.frame_advance
                    && prior.delay_seconds == update.delay_seconds
                    && prior.duration_seconds == update.duration_seconds
                    && prior.easing == update.easing
                    && prior.opt1 == update.opt1
            }) {
                previous.value = value;
            } else {
                update.initial_value = frame
                    .values
                    .iter()
                    .find(|(key, _)| *key == target)
                    .map(|(_, value)| value.clone())
                    .or(pending);
                frame.scheduled.push(update);
            }
        } else {
            replace(&mut frame.values, target, value);
        }
    }

    fn drain(&mut self) -> Vec<SongReplayImmediateUpdates> {
        self.touched
            .drain(..)
            .map(|index| self.frames.remove(&index).unwrap())
            .filter(|frame| {
                frame.tween_reset
                    || !frame.values.is_empty()
                    || !frame.scheduled.is_empty()
                    || !frame.final_values.is_empty()
            })
            .collect()
    }
}

impl Actors {
    pub(in crate::rust_engine) fn set_song_pending_render_updates(
        &self,
        screen: ActorScene,
        values: &[(usize, Target, UpdateValue)],
    ) -> bool {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame.map(|f| f.0) != Some(screen.id) {
            return false;
        }
        let Some(capture) = store
            .scenes
            .get_mut(&screen.id)
            .and_then(|s| s.song_session.as_mut())
            .and_then(|s| s.messages.as_mut())
        else {
            return false;
        };
        if values.iter().any(|(index, target, _)| {
            !capture.indices.values().any(|i| i == index)
                || !song_properties::TARGETS.contains(target)
        }) {
            return false;
        }
        capture.immediate.pending.clear();
        for (index, target, value) in values {
            replace(
                capture.immediate.pending.entry(*index).or_default(),
                *target,
                value.clone(),
            );
        }
        true
    }

    pub(in crate::rust_engine) fn drain_song_immediate_updates(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongReplayImmediateUpdates>> {
        let mut frames = self.drain_song_property_updates(screen)?;
        for frame in &mut frames {
            frame.values.retain(|(target, _)| TARGETS.contains(target));
            frame
                .final_values
                .retain(|(target, _)| TARGETS.contains(target));
            frame
                .scheduled
                .retain(|update| TARGETS.contains(&update.target));
        }
        frames.retain(|f| {
            f.tween_reset
                || !f.values.is_empty()
                || !f.final_values.is_empty()
                || !f.scheduled.is_empty()
        });
        Some(frames)
    }

    pub(in crate::rust_engine) fn drain_song_property_updates(
        &self,
        screen: ActorScene,
    ) -> Option<Vec<SongReplayImmediateUpdates>> {
        let mut store = self.store.lock().unwrap();
        if store.replay_frame?.0 != screen.id {
            return None;
        }
        Some(
            store
                .scenes
                .get_mut(&screen.id)?
                .song_session
                .as_mut()?
                .messages
                .as_mut()?
                .immediate
                .drain(),
        )
    }
}

// A capture's actor IDs are traced by its enclosing scene. Lookup after each Lua
// access also tolerates authored reentry without holding a Store lock across it.
pub(super) fn context(store: &Store, id: TableId) -> Option<(u64, usize)> {
    if store.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    let (owner, _) = store.replay_frame?;
    if store.retired_scenes.contains_key(&owner) {
        return None;
    }
    let capture = store
        .scenes
        .get(&owner)?
        .song_session
        .as_ref()?
        .messages
        .as_ref()?;
    Some((owner, *capture.indices.get(&id)?))
}

pub(super) fn record(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    target: Target,
    value: UpdateValue,
) {
    if context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let mut guard = store.lock().unwrap();
    let Some((owner, index)) = context(&guard, id) else {
        return;
    };
    let dispatch = guard.replay_dispatch;
    let message = guard.active_message.clone();
    let capture = guard
        .scenes
        .get_mut(&owner)
        .unwrap()
        .song_session
        .as_mut()
        .unwrap()
        .messages
        .as_mut()
        .unwrap();
    if let Some(message) = message {
        capture.write(
            message,
            crate::SongLuaStatefulMessageWrite {
                overlay_index: index,
                beat,
                target,
                value: value.clone(),
                delay_seconds: dispatch.map_or(0., |scope| scope.delay),
                duration_seconds: 0.,
                easing: None,
                opt1: None,
            },
        );
    }
    let scheduled = dispatch.map(|dispatch| SongReplayScheduledUpdate {
        progress: None,
        dispatch_seconds: dispatch.seconds,
        frame_advance: 0.,
        initial_value: None,
        delay_seconds: dispatch.delay,
        duration_seconds: 0.,
        easing: None,
        opt1: None,
        target,
        value: value.clone(),
    });
    capture.immediate.record(index, target, value, scheduled);
}

pub(super) fn delta(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: &crate::SongLuaOverlayStateDelta,
    immediate: bool,
) {
    if !immediate || context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let mut state = crate::SongLuaOverlayState::default();
    crate::apply_overlay_delta(&mut state, delta);
    for &target in TARGETS {
        if delta.has_update_target(target) {
            record(
                call,
                store,
                id,
                target,
                crate::perframe::overlay_state_update_value(&state, target),
            );
        }
    }
}

pub(super) fn cancel(call: &mut HostCall<'_>, store: &Shared, id: TableId, finish: bool) {
    if context(&store.lock().unwrap(), id).is_none() {
        return;
    }
    let beat = effects::values(call, false).map_or(0., |values| values[0]);
    let mut guard = store.lock().unwrap();
    let Some((owner, index)) = context(&guard, id) else {
        return;
    };
    let message = guard.active_message.clone();
    let capture = guard
        .scenes
        .get_mut(&owner)
        .unwrap()
        .song_session
        .as_mut()
        .unwrap()
        .messages
        .as_mut()
        .unwrap();
    let pending = capture.immediate.pending.remove(&index).unwrap_or_default();
    let frame = capture.immediate.touch(index);
    frame.tween_reset = true;
    // Stop cannot discard an immediate setter merely because it was published
    // by a queued command. Finish promotes those pending publications now.
    if finish {
        let mut values = pending;
        for update in std::mem::take(&mut frame.scheduled) {
            replace(&mut values, update.target, update.value);
        }
        let render_getters: Vec<_> = values
            .iter()
            .filter(|(target, _)| song_properties::TARGETS.contains(target))
            .cloned()
            .collect();
        for (target, value) in &values {
            replace(&mut frame.values, *target, value.clone());
            replace(&mut frame.final_values, *target, value.clone());
        }
        if let Some(message) = message {
            for (target, value) in values {
                capture.write(
                    message.clone(),
                    crate::SongLuaStatefulMessageWrite {
                        overlay_index: index,
                        beat,
                        target,
                        value,
                        delay_seconds: 0.,
                        duration_seconds: 0.,
                        easing: None,
                        opt1: None,
                    },
                );
            }
        }
        let actor = guard.actors.get_mut(&id).unwrap();
        for (target, value) in render_getters {
            crate::perframe::set_overlay_state_update_value(
                &mut actor.state.render,
                target,
                &value,
            );
            if let (Target::DrawOrder, UpdateValue::I32(order)) = (target, value) {
                actor.state.draw_order = order;
            }
            if target == Target::Fov {
                actor.state.render.fov = actor.state.render.fov.filter(|fov| *fov != -1.);
            }
        }
    }
}

