fn compare_tween_progress(
    pair: &mut Pair,
    actors: &[(mlua::Table, deadlib_lua::TableId)],
) -> std::collections::HashMap<deadlib_lua::TableId, deadsync_song_lua::rust_engine::SongTweenReplay>
{
    let expected = test_support::legacy_song_tween_replay(&pair.native);
    let actual = pair.rust.capture_song_tween_replay(pair.scene).unwrap();
    for (a, b) in actors {
        assert_eq!(actual.get(b), expected.get(&(a.to_pointer() as usize)));
    }
    assert_eq!(
        pair.rust.capture_song_tween_replay(pair.scene).unwrap(),
        actual,
        "sampling twice must not duplicate hold samples"
    );
    actual
}
fn compare_finished_progress(
    pair: &mut Pair,
    actors: &[(mlua::Table, deadlib_lua::TableId)],
    native: &test_support::LegacySongActivation,
    rust: &SongActivation,
) {
    let actual = compare_tween_progress(pair, actors);
    let tables = actors.iter().map(|(a, _)| a.clone()).collect::<Vec<_>>();
    let expected = test_support::legacy_finish_song_tween_replay(&pair.native, &tables, native);
    for (a, b) in actors {
        let mut blocks = rust.tweens[b].blocks.clone();
        if let Some(replay) = actual.get(b) {
            replay.apply_startup_progress(&mut blocks, &rust.tweens[b]);
        }
        assert_eq!(blocks, expected[&(a.to_pointer() as usize)]);
    }
}

