        test_support::legacy_advance_song_replay(&pair.native, &native, time, delta).unwrap();
        assert!(
            pair.rust
                .advance_song_replay(pair.scene, time, delta)
                .unwrap()
        );
        let capture = compare_tween_progress(&mut pair, &actors);
        if index == 1 {
            assert_eq!(
                capture[&actors[1].1].progress[0],
                [[10.125, 1.], [10.25, 0.25]]
            );
            assert_eq!(
                capture[&actors[2].1].progress[0],
                [[10.1875, 0.5], [10.25, 0.375]]
            );
            pair.script("saved.parent:hibernate(.75);collectgarbage()");
        }
        if index == 2 {
            assert_eq!(
