fn begin_message_replay(
    pair: &mut Pair,
    native: &test_support::LegacySongActivation,
    rust: &SongActivation,
    keys: &[&str],
) {
    test_support::legacy_discover_song_startup_commands(&pair.native, native, false).unwrap();
    pair.rust
        .discover_song_startup_commands(pair.scene, rust)
        .unwrap();
    test_support::legacy_begin_song_replay_clock(&pair.native).unwrap();
    let actors: Vec<_> = keys.iter().map(|key| saved_pair(pair, key)).collect();
    let initial = deadsync_song_lua::SongLuaOverlayState::default();
    let overlays: Vec<_> = actors.iter().map(|(a, _)| (a.clone(), initial)).collect();
    test_support::legacy_begin_song_replay(&pair.native, &overlays, native).unwrap();
    test_support::legacy_begin_song_message_capture(
        &pair.native,
        &actors
            .iter()
            .enumerate()
            .map(|(i, (a, _))| (a.clone(), i))
            .collect::<Vec<_>>(),
    );
    let overlays: Vec<_> = actors.iter().map(|(_, b)| (*b, initial)).collect();
    assert!(
        pair.rust
            .begin_song_replay(pair.scene, &overlays, rust)
            .unwrap()
    );
}

